<?php
namespace Xdecaro\Component\Decaropeople\Administrator\Service;
defined('_JEXEC') or die;
use Joomla\CMS\WebAsset\WebAssetManager;
final class CoreIntegrationService { public const COMPONENT='com_decaropeople'; public const MINIMUM_CORE='1.1.0'; public function getVersion(): string { return class_exists(\Xdecaro\Core\Version::class)?trim((string)\Xdecaro\Core\Version::VERSION):''; } public function isReferenceApiAvailable(): bool { return class_exists(\Xdecaro\Core\Integration\EntityReference::class)&&class_exists(\Xdecaro\Core\Integration\RelationReference::class); } public function enableUi(WebAssetManager $webAssets): bool { $v=$this->getVersion(); if($v===''||version_compare($v,self::MINIMUM_CORE,'<')||!class_exists(\Xdecaro\Core\Asset\AssetService::class)) return false; try { return (new \Xdecaro\Core\Asset\AssetService())->useComponents($webAssets); } catch (\Throwable) { return false; } } public function createEntityReference(int|string $id): object { if(!$this->isReferenceApiAvailable()) throw new \RuntimeException('Core by xdecaro reference API is unavailable.'); return new \Xdecaro\Core\Integration\EntityReference(self::COMPONENT,'person',$id); } }
